<?php
require __DIR__ . '/db.php';
[$from, $to] = dates();
$error = null; $stats = ['barang'=>0,'nota'=>0,'omzet'=>0]; $recent = []; $categories = []; $suppliers = [];
try {
    $stats['barang'] = (int)db()->query('SELECT COUNT(*) FROM barang')->fetchColumn();
    $s = db()->prepare('SELECT COUNT(*), COALESCE(SUM(jumlah),0) FROM penjualan WHERE tanggal BETWEEN ? AND ?');
    $s->execute([$from,$to]); [$stats['nota'],$stats['omzet']] = $s->fetch(PDO::FETCH_NUM);
    $s = db()->prepare('SELECT tanggal,kode,nama_pelanggan,jumlah,operator FROM penjualan WHERE tanggal BETWEEN ? AND ? ORDER BY tanggal DESC,jam DESC LIMIT 100');
    $s->execute([$from,$to]); $recent = $s->fetchAll();
    $categories = db()->query("SELECT DISTINCT kategori FROM barang WHERE kategori IS NOT NULL AND kategori <> '' ORDER BY kategori")->fetchAll(PDO::FETCH_COLUMN);
    $suppliers = db()->query("SELECT DISTINCT supplier FROM barang WHERE supplier IS NOT NULL AND supplier <> '' ORDER BY supplier")->fetchAll(PDO::FETCH_COLUMN);
} catch (Throwable $e) { $error = $e->getMessage(); }
function rupiah($v): string { return 'Rp ' . number_format((float)$v,0,',','.'); }
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Export Data Toko</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#182230;font:15px system-ui,Segoe UI,sans-serif}.wrap{max-width:1100px;margin:40px auto;padding:0 20px}h1{margin-bottom:4px}.muted{color:#667085}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:24px 0}.card{background:#fff;border:1px solid #e4e7ec;border-radius:14px;padding:20px;box-shadow:0 2px 8px #1018280d}.big{font-size:27px;font-weight:700;margin-top:8px}.actions{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.actions label{display:grid;gap:6px}input,select{padding:10px;border:1px solid #ccd1da;border-radius:8px;min-width:150px}.btn{display:inline-block;padding:11px 16px;border:0;border-radius:8px;background:#1570ef;color:#fff;text-decoration:none;font-weight:650;cursor:pointer}.green{background:#079455}.error{background:#fff1f0;color:#b42318;padding:14px;border-radius:8px;margin:18px 0}table{width:100%;border-collapse:collapse;margin-top:12px}th,td{text-align:left;padding:11px;border-bottom:1px solid #eaecf0}th{background:#f9fafb}.divider{border:0;border-top:1px solid #eaecf0;margin:22px 0}@media(max-width:700px){.grid{grid-template-columns:1fr}.card{overflow:auto}}
</style></head><body><main class="wrap"><h1>Export Data Toko</h1><div class="muted">Database: toko_1_3</div>
<?php if($error): ?><div class="error"><b>Database belum terhubung.</b><br><?=htmlspecialchars($error)?><br>Jalankan MySQL dan impor file SQL terlebih dahulu.</div><?php endif ?>
<section class="grid"><div class="card"><span class="muted">Jumlah barang</span><div class="big"><?=number_format($stats['barang'],0,',','.')?></div></div><div class="card"><span class="muted">Nota periode ini</span><div class="big"><?=number_format((float)$stats['nota'],0,',','.')?></div></div><div class="card"><span class="muted">Omzet periode ini</span><div class="big"><?=rupiah($stats['omzet'])?></div></div></section>
<section class="card"><h2>Export List Barang</h2><form class="actions" action="export.php" method="get"><input type="hidden" name="type" value="barang"><label>Cari kode / nama<input name="search" placeholder="Semua barang"></label><label>Kategori<select name="kategori"><option value="">Semua kategori</option><?php foreach($categories as $v): ?><option value="<?=htmlspecialchars($v)?>"><?=htmlspecialchars($v)?></option><?php endforeach ?></select></label><label>Supplier<select name="supplier"><option value="">Semua supplier</option><?php foreach($suppliers as $v): ?><option value="<?=htmlspecialchars($v)?>"><?=htmlspecialchars($v)?></option><?php endforeach ?></select></label><label>Stok<select name="stok"><option value="semua">Semua stok</option><option value="tersedia">Stok tersedia</option><option value="habis">Stok habis</option></select></label><button class="btn green" type="submit">Export Barang</button></form><hr class="divider"><h2>Export Penjualan</h2><form class="actions" method="get"><label>Dari tanggal<input type="date" name="from" value="<?=htmlspecialchars($from)?>"></label><label>Sampai tanggal<input type="date" name="to" value="<?=htmlspecialchars($to)?>"></label><button class="btn" type="submit">Tampilkan</button><a class="btn green" href="export.php?type=penjualan&amp;from=<?=urlencode($from)?>&amp;to=<?=urlencode($to)?>">Export Penjualan</a></form></section>
<section class="card" style="margin-top:16px"><h2>Penjualan terbaru</h2><table><thead><tr><th>Tanggal</th><th>Faktur</th><th>Pelanggan</th><th>Total</th><th>Operator</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td><?=htmlspecialchars($r['tanggal'])?></td><td><?=htmlspecialchars($r['kode'])?></td><td><?=htmlspecialchars($r['nama_pelanggan'] ?: 'Tanpa Nama')?></td><td><?=rupiah($r['jumlah'])?></td><td><?=htmlspecialchars($r['operator'])?></td></tr><?php endforeach ?></tbody></table></section>
</main></body></html>
